defmodule AshPhoenixStarter.Farms.FarmPlantingHarvest do
  use Ash.Resource,
    domain: Elixir.AshPhoenixStarter.Farms,
    data_layer: AshPostgres.DataLayer

  postgres do
    table "farm_planting_harvest"
  end

  multitenancy do
    strategy :context
  end

  preparations do
    prepare AshPhoenixStarter.Preparations.SetTenant
  end

  changes do
    change AshPhoenixStarter.Changes.SetTenant
  end

  attributes do
    # Primary Key generated by Postgres via uuid_generate_v7()
    uuid_primary_key :id do
      generated? true
      allow_nil? true
      writable? false
    end

    attribute :harvest_date, :date do
      allow_nil? false
      public? true
    end

    attribute :quantity_harvested, :float do
      allow_nil? false
      public? true
    end

    # Optional fields mapping from text to string
    attribute :quality_grade, :string do
      allow_nil? true
      public? true
    end

    attribute :notes, :string do
      allow_nil? true
      public? true
    end

    # Database-managed timestamps
    attribute :inserted_at, :utc_datetime_usec do
      generated? true
      allow_nil? true
      writable? false
    end

    attribute :updated_at, :utc_datetime_usec do
      generated? true
      allow_nil? true
      writable? false
    end
  end

  relationships do
    # Required relationship back to the farm planting record
    belongs_to :planting, AshPhoenixStarter.Farms.FarmPlanting do
      attribute_type :uuid
      allow_nil? false
      public? true
    end
  end

  actions do
    defaults [:read, :destroy]

    create :create do
      primary? true
      accept [:harvest_date, :quantity_harvested, :quality_grade, :notes, :planting_id]
    end

    update :update do
      primary? true
      accept [:harvest_date, :quantity_harvested, :quality_grade, :notes, :planting_id]
    end
  end
end
